<?php

declare(strict_types=1);

use PortLibs\Pandoc\AstNode;
use PortLibs\Pandoc\CitationCslProcessor;
use PortLibs\Pandoc\MarkdownReader;
use PortLibs\Pandoc\MarkdownWriter;
use PortLibs\Pandoc\PandocJsonReader;
use PortLibs\Pandoc\WordPressBlockWriter;

$cslJson = static fn (): string => json_encode([
    [
        'id' => 'smith1899',
        'type' => 'book',
        'title' => 'Migration Patterns',
        'author' => [
            ['family' => 'Smith', 'given' => 'Ada'],
        ],
        'issued' => ['date-parts' => [[1899]]],
        'publisher' => 'Archive Press',
        'DOI' => '10.1234/source',
    ],
    [
        'id' => 'doe2020',
        'type' => 'article-journal',
        'title' => 'Field Notes',
        'container-title' => 'Journal of Imports',
        'author' => [
            ['family' => 'Doe', 'given' => 'Jane'],
            ['family' => 'Roe', 'given' => 'Pat'],
        ],
        'issued' => ['date-parts' => [[2020, 6, 1]]],
        'page' => '55-60',
        'URL' => 'https://example.test/field-notes',
    ],
    [
        'id' => 'wp-team',
        'type' => 'webpage',
        'title' => 'Reviewer Log',
        'author' => [
            ['literal' => 'WordPress Migration Team'],
        ],
        'issued' => ['date-parts' => [['2024']]],
        'URL' => 'https://example.test/reviewer-log',
    ],
    [
        'id' => 'https://example.com/bib?name=foobar&date=2000',
        'type' => 'webpage',
        'title' => 'URL Key Source',
        'issued' => ['date-parts' => [[2000]]],
        'URL' => 'https://example.com/bib?name=foobar&date=2000',
    ],
], JSON_THROW_ON_ERROR);

$citation = static function (string $id, string $text, string $mode = 'normal', array $attrs = []): AstNode {
    return new AstNode('citation', [
        'id' => $id,
        'text' => $text,
        'mode' => $mode,
        ...$attrs,
    ], [
        new AstNode('text', ['text' => $text]),
    ]);
};

return [
    'normalizes csl json records and renders bounded author date citation clusters' => static function (TestRunner $t) use ($cslJson, $citation): void {
        $processor = CitationCslProcessor::fromJson($cslJson());
        $prefixed = $citation('smith1899', '[@smith1899]', 'normal', ['prefix' => 'see', 'suffix' => 'p. 7']);
        $journal = $citation('doe2020', '[@doe2020]');
        $suppressed = $citation('smith1899', '[-@smith1899]', 'suppress_author', ['suffix' => [
            new AstNode('text', ['text' => 'pp.']),
            new AstNode('space'),
            new AstNode('code', ['text' => '8-9']),
        ]]);
        $authorText = $citation('doe2020', '@doe2020', 'author_in_text', ['suffix' => 'ch. 2']);
        $team = $citation('wp-team', '@wp-team', 'author_in_text');
        $missing = $citation('missing', '[@missing]');

        $t->same('(see Smith 1899, p. 7; Doe and Roe 2020; 1899, pp. 8-9)', $processor->renderCitationCluster([$prefixed, $journal, $suppressed]));
        $t->same('Doe and Roe (2020, ch. 2)', $processor->renderCitationCluster([$authorText]));
        $t->same('WordPress Migration Team (2024)', $processor->renderCitationCluster([$team]));
        $t->same('([@missing])', $processor->renderCitationCluster([$missing]));
        $t->same('Migration Patterns', $processor->item('smith1899')['title'] ?? null);
        $t->same('Journal of Imports', $processor->item('doe2020')['containerTitle'] ?? null);
        $t->same('https://example.test/reviewer-log', $processor->item('wp-team')['url'] ?? null);

        $normalized = $processor->normalizeCitation($prefixed);
        $t->same('citation', $normalized->type);
        $t->same('(see Smith 1899, p. 7)', $normalized->attr('rendered'));
        $t->same('Smith', $normalized->attr('cslLabel'));
        $t->same('1899', $normalized->attr('cslYear'));
        $t->same(false, (bool) $normalized->attr('missingCslItem', false));
        $t->same('smith1899', $normalized->attr('cslItem')['id'] ?? null);

        $missingNormalized = $processor->normalizeCitation($missing);
        $t->same('[@missing]', $missingNormalized->attr('rendered'));
        $t->same(true, (bool) $missingNormalized->attr('missingCslItem', false));
    },
    'preserves citation prefix and suffix review metadata for csl handoff' => static function (TestRunner $t) use ($citation): void {
        $processor = CitationCslProcessor::fromItems([
            [
                'id' => 'affix-source',
                'type' => 'report',
                'title' => 'Affix Source Packet',
                'author' => [
                    ['family' => 'Ng', 'given' => 'Nia'],
                ],
                'issued' => ['date-parts' => [[2026]]],
            ],
            [
                'id' => 'plain-source',
                'type' => 'report',
                'title' => 'Plain Source Packet',
                'author' => [
                    ['family' => 'Roe', 'given' => 'Pat'],
                ],
                'issued' => ['date-parts' => [[2025]]],
            ],
        ])->withCslStyle(
            <<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<style xmlns="http://purl.org/net/xbiblio/csl" version="1.0" class="in-text">
  <citation>
    <layout prefix="[" suffix="]" delimiter="; ">
      <group delimiter=" | ">
        <names variable="author"/>
        <text variable="citation-prefix"/>
        <text variable="citation-suffix"/>
        <text variable="citation-affix-summary"/>
        <text variable="locator-label"/>
        <text variable="locator"/>
      </group>
    </layout>
  </citation>
  <bibliography>
    <layout delimiter=" :: ">
      <text variable="title"/>
      <date variable="issued"><date-part name="year"/></date>
    </layout>
  </bibliography>
</style>
XML
        );

        $affixed = $citation('affix-source', '[see also @affix-source, p. 42]', 'normal', [
            'prefix' => [
                new AstNode('emphasis', [], [new AstNode('text', ['text' => 'see'])]),
                new AstNode('space'),
                new AstNode('text', ['text' => 'also']),
            ],
            'suffix' => [
                new AstNode('text', ['text' => 'p.']),
                new AstNode('space'),
                new AstNode('code', ['text' => '42']),
            ],
        ]);
        $plain = $citation('plain-source', '[@plain-source]');

        $t->same(
            '[Ng | see also | p. 42 | prefix: see also; suffix: p. 42 | page | 42; Roe]',
            $processor->renderCitationCluster([$affixed, $plain])
        );

        $normalized = $processor->normalizeCitation($affixed);
        $t->same('see also', $normalized->attr('cslCitationPrefix'));
        $t->same('p. 42', $normalized->attr('cslCitationSuffix'));
        $t->same('prefix: see also; suffix: p. 42', $normalized->attr('cslCitationAffixSummary'));
        $t->same('citation-locator-suffix-inferred', $normalized->attr('cslLocatorDiagnosticReasons'));
        $t->same('inferred', $normalized->attr('cslLocator')['sourceClass'] ?? null);

        $group = $processor->normalizeCitationGroup(new AstNode('citation_group', [], [$affixed, $plain]));
        $t->same('affix-source', $group->attr('cslCitationAffixes')[0]['id'] ?? null);
        $t->same('see also', $group->attr('cslCitationAffixes')[0]['prefix'] ?? null);
        $t->same('p. 42', $group->attr('cslCitationAffixes')[0]['suffix'] ?? null);
        $t->same('affix-source [prefix: see also; suffix: p. 42]', $group->attr('cslCitationAffixSummary'));

        $document = new AstNode('document', [], [
            new AstNode('paragraph', [], [
                new AstNode('text', ['text' => 'Affix source ']),
                new AstNode('citation_group', [], [$affixed, $plain]),
                new AstNode('text', ['text' => ' stays reviewable.']),
            ]),
        ]);
        $blocks = (new WordPressBlockWriter())->write($processor->appendBibliography($document, 'Works Cited'));
        $t->contains('<p>Affix source [Ng | see also | p. 42 | prefix: see also; suffix: p. 42 | page | 42; Roe] stays reviewable.</p>', $blocks);
        $t->contains('<dt>Ng 2026</dt><dd>Affix Source Packet :: 2026</dd>', $blocks);
        $t->contains('<dt>Roe 2025</dt><dd>Plain Source Packet :: 2025</dd>', $blocks);
    },
    'normalizes csl date variables and name particles for bibliography handoff' => static function (TestRunner $t) use ($citation): void {
        $processor = CitationCslProcessor::fromItems([
            [
                'id' => 'particle-source',
                'type' => 'webpage',
                'title' => 'Source Packet',
                'author' => [
                    [
                        'family' => 'Cruz',
                        'given' => 'Ana Maria',
                        'non-dropping-particle' => 'de la',
                        'suffix' => 'Jr.',
                        'comma-suffix' => true,
                    ],
                ],
                'issued' => ['date-parts' => [[2026, 6, 4]]],
                'accessed' => ['date-parts' => [['2026', '06', '05']]],
                'URL' => 'https://example.test/source-packet',
            ],
            [
                'id' => 'edited-manual',
                'type' => 'book',
                'title' => 'Edited Migration Manual',
                'editor' => [
                    [
                        'family' => 'Curator',
                        'given' => 'Eli',
                        'suffix' => 'III',
                        'comma-suffix' => false,
                    ],
                ],
                'issued' => ['literal' => 'forthcoming'],
                'publisher' => 'Review Press',
            ],
        ]);

        $particle = $processor->item('particle-source');
        $t->same([2026, 6, 4], $particle['issuedDate']['parts'] ?? null);
        $t->same(2026, $particle['issuedDate']['year'] ?? null);
        $t->same('2026-06-04', $particle['issuedDate']['display'] ?? null);
        $t->same([2026, 6, 5], $particle['accessedDate']['parts'] ?? null);
        $t->same('2026-06-05', $particle['accessedDate']['display'] ?? null);
        $t->same('de la', $particle['authors'][0]['nonDroppingParticle'] ?? null);
        $t->same('Jr.', $particle['authors'][0]['suffix'] ?? null);
        $t->same(true, $particle['authors'][0]['commaSuffix'] ?? null);
        $t->same('(de la Cruz 2026)', $processor->renderCitationCluster([$citation('particle-source', '[@particle-source]')]));
        $t->same('de la Cruz, Ana Maria, Jr. Source Packet. 2026. https://example.test/source-packet. Accessed 2026-06-05.', $processor->renderBibliographyEntry('particle-source'));

        $edited = $processor->item('edited-manual');
        $t->same(null, $edited['issuedDate']['year'] ?? null);
        $t->same([], $edited['issuedDate']['parts'] ?? null);
        $t->same('forthcoming', $edited['issuedDate']['literal'] ?? null);
        $t->same('forthcoming', $edited['issuedDate']['display'] ?? null);
        $t->same('III', $edited['editors'][0]['suffix'] ?? null);
        $t->same(false, $edited['editors'][0]['commaSuffix'] ?? null);
        $t->same('(Curator forthcoming)', $processor->renderCitationCluster([$citation('edited-manual', '[@edited-manual]')]));
        $t->same('Curator, Eli III. Edited Migration Manual. Review Press, forthcoming.', $processor->renderBibliographyEntry('edited-manual'));

        $bibliography = $processor->bibliographyDefinitionList(['particle-source', 'edited-manual']);
        $t->same('de la Cruz 2026', $bibliography->children[0]->children[0]->attr('text'));
        $t->same('Curator forthcoming', $bibliography->children[1]->children[0]->attr('text'));
    },
    'parses bounded bibtex and biblatex entries into csl bibliography items' => static function (TestRunner $t) use ($citation): void {
        $bibtex = <<<'BIB'
@comment{ignored by the bounded bibliography handoff}

@book{smith1899,
  author    = {Smith, Ada},
  title     = {Migration Patterns},
  year      = {1899},
  publisher = {Archive Press},
  doi       = {10.1234/source}
}

@article{doe2020,
  author       = {Doe, Jane and Roe, Pat},
  title        = {Field Notes},
  journaltitle = {Journal of Imports},
  date         = {2020-06-01},
  pages        = {55--60},
  url          = {https://example.test/field-notes},
  urldate      = {2026-06-04}
}

@online{wp-team,
  author = {{WordPress Migration Team}},
  title  = {Reviewer Log},
  date   = {2024},
  url    = {https://example.test/reviewer-log}
}
BIB;

        $items = CitationCslProcessor::bibtexItems($bibtex);
        $t->same(3, count($items));
        $t->same('smith1899', $items[0]['id']);
        $t->same('book', $items[0]['type']);
        $t->same('article-journal', $items[1]['type']);
        $t->same('Journal of Imports', $items[1]['container-title']);
        $t->same('55-60', $items[1]['page']);
        $t->same('webpage', $items[2]['type']);
        $t->same([['literal' => 'WordPress Migration Team']], $items[2]['author']);

        $processor = CitationCslProcessor::fromBibtex($bibtex);
        $journal = $processor->item('doe2020');
        $t->same([2020, 6, 1], $journal['issuedDate']['parts'] ?? null);
        $t->same('2020-06-01', $journal['issuedDate']['display'] ?? null);
        $t->same([2026, 6, 4], $journal['accessedDate']['parts'] ?? null);
        $t->same('Doe and Roe', $journal === null ? null : $processor->normalizeCitation($citation('doe2020', '[@doe2020]'))->attr('cslLabel'));
        $t->same('(Smith 1899; Doe and Roe 2020; WordPress Migration Team 2024)', $processor->renderCitationCluster([
            $citation('smith1899', '[@smith1899]'),
            $citation('doe2020', '[@doe2020]'),
            $citation('wp-team', '[@wp-team]'),
        ]));
        $t->same('Doe, Jane; Roe, Pat. Field Notes. Journal of Imports. 2020. 55-60. https://example.test/field-notes. Accessed 2026-06-04.', $processor->renderBibliographyEntry('doe2020'));

        $document = (new MarkdownReader())->read('Review cites [see @smith1899; @doe2020, pp. 55-60] and @wp-team.');
        $processed = $processor->appendBibliography($document, 'Works Cited');
        $markdown = (new MarkdownWriter())->write($processed);
        $t->contains('Review cites (see Smith 1899; Doe and Roe 2020, pp. 55-60) and WordPress Migration Team (2024).', $markdown);
        $t->contains('Smith 1899' . "\n" . ':   Smith, Ada. Migration Patterns. Archive Press, 1899. DOI 10.1234/source.', $markdown);
        $t->contains('WordPress Migration Team 2024' . "\n" . ':   WordPress Migration Team. Reviewer Log. 2024. https://example.test/reviewer-log.', $markdown);
    },
    'normalizes biblatex status and taxonomy aliases into csl handoff' => static function (TestRunner $t) use ($citation): void {
        $bibtex = <<<'BIB'
@article{biblatex-status-hyphen,
  author             = {Ng, Nia},
  title              = {BibLaTeX Status Hyphen Packet},
  journaltitle       = {Migration Review},
  date               = {2026},
  publication-status = {accepted},
  keyword-list       = {source audit; release queue},
  category-list      = {biblatex, taxonomy}
}

@report{biblatex-status-camel,
  author            = {Roe, Rae},
  title             = {BibLaTeX Status Camel Packet},
  institution       = {Archive Desk},
  date              = {2025},
  publicationStatus = {in press},
  keywordList       = {review queue, compact alias},
  categoryList      = {handoff; csl}
}

@misc{biblatex-status-pubstate,
  author     = {Kim, Kai},
  title      = {BibLaTeX Status Pubstate Packet},
  date       = {2024},
  pubstate   = {preprint},
  keywords   = {conference, source packet},
  categories = {legacy; review}
}
BIB;

        $processor = CitationCslProcessor::fromBibtex($bibtex);
        $hyphen = $processor->item('biblatex-status-hyphen');
        $camel = $processor->item('biblatex-status-camel');
        $pubstate = $processor->item('biblatex-status-pubstate');
        $t->same('accepted', $hyphen['status'] ?? null);
        $t->same(['source audit', 'release queue'], $hyphen['keywords'] ?? null);
        $t->same('source audit; release queue', $hyphen['keywordSummary'] ?? null);
        $t->same(['biblatex', 'taxonomy'], $hyphen['categories'] ?? null);
        $t->same('biblatex; taxonomy', $hyphen['categorySummary'] ?? null);
        $t->same('in press', $camel['status'] ?? null);
        $t->same(['review queue', 'compact alias'], $camel['keywords'] ?? null);
        $t->same(['handoff', 'csl'], $camel['categories'] ?? null);
        $t->same('preprint', $pubstate['status'] ?? null);
        $t->same(['conference', 'source packet'], $pubstate['keywords'] ?? null);
        $t->same(['legacy', 'review'], $pubstate['categories'] ?? null);

        $styled = $processor->withCslStyle(<<<'XML'
<?xml version="1.0" encoding="UTF-8"?>
<style xmlns="http://purl.org/net/xbiblio/csl" version="1.0" class="in-text" default-locale="en-US">
  <info>
    <title>Bounded BibLaTeX Status Taxonomy Alias Review</title>
    <id>https://example.test/styles/bounded-biblatex-status-taxonomy-alias-review</id>
    <updated>2026-06-14T05:27:00+00:00</updated>
  </info>
  <citation>
    <layout prefix="[" suffix="]" delimiter="; ">
      <choose>
        <if variable="status keyword-summary category-summary" match="all">
          <group delimiter=" | ">
            <names variable="author"/>
            <text variable="status"/>
            <text variable="keyword-summary"/>
            <text variable="category-summary"/>
          </group>
        </if>
        <else>
          <text value="missing-status-taxonomy"/>
        </else>
      </choose>
    </layout>
  </citation>
  <bibliography>
    <layout delimiter=" :: ">
      <text variable="title"/>
      <text variable="status"/>
      <text variable="keywords"/>
      <text variable="category-summary"/>
    </layout>
  </bibliography>
</style>
XML);

        $summary = $styled->cslStyleSummary();
        $branch = $summary['citationRendering'][0]['branches'][0] ?? [];
        $t->same('Bounded BibLaTeX Status Taxonomy Alias Review', $summary['title'] ?? null);
        $t->same(['status', 'keyword-summary', 'category-summary'], $branch['variables'] ?? null);
        $t->same('[Ng | accepted | source audit; release queue | biblatex; taxonomy; Roe | in press | review queue; compact alias | handoff; csl; Kim | preprint | conference; source packet | legacy; review]', $styled->renderCitationCluster([
            $citation('biblatex-status-hyphen', '[@biblatex-status-hyphen]'),
            $citation('biblatex-status-camel', '[@biblatex-status-camel]'),
            $citation('biblatex-status-pubstate', '[@biblatex-status-pubstate]'),
        ]));
        $t->same('BibLaTeX Status Hyphen Packet :: accepted :: source audit, release queue :: biblatex; taxonomy', $styled->renderBibliographyEntry('biblatex-status-hyphen'));
        $t->same('BibLaTeX Status Camel Packet :: in press :: review queue, compact alias :: handoff; csl', $styled->renderBibliographyEntry('biblatex-status-camel'));
        $t->same('BibLaTeX Status Pubstate Packet :: preprint :: conference, source packet :: legacy; review', $styled->renderBibliographyEntry('biblatex-status-pubstate'));

        $document = (new MarkdownReader())->read('BibLaTeX status aliases [@biblatex-status-hyphen; @biblatex-status-camel; @biblatex-status-pubstate] keep taxonomy metadata visible.');
        $blocks = (new WordPressBlockWriter())->write($styled->appendBibliography($document, 'Works Cited'));
        $t->contains('<p>BibLaTeX status aliases [Ng | accepted | source audit; release queue | biblatex; taxonomy; Roe | in press | review queue; compact alias | handoff; csl; Kim | preprint | conference; source packet | legacy; review] keep taxonomy metadata visible.</p>', $blocks);
        $t->contains('<dt>Ng 2026</dt><dd>BibLaTeX Status Hyphen Packet :: accepted :: source audit, release queue :: biblatex; taxonomy</dd>', $blocks);
        $t->contains('<dt>Roe 2025</dt><dd>BibLaTeX Status Camel Packet :: in press :: review queue, compact alias :: handoff; csl</dd>', $blocks);
        $t->contains('<dt>Kim 2024</dt><dd>BibLaTeX Status Pubstate Packet :: preprint :: conference, source packet :: legacy; review</dd>', $blocks);
    },
