        <date variable="issued">
          <date-part name="year"/>
        </date>
      </group>
    </layout>
  </citation>
  <bibliography>
    <layout delimiter=" | ">
      <names variable="editor" delimiter="; ">
        <name initialize-with=". " name-as-sort-order="all"/>
        <label form="short" plural="always" prefix=", " quotes="true"/>
      </names>
      <text variable="title"/>
    </layout>
  </bibliography>
</style>
XML
        );

